## 4. Define Your Own Program

This is the part that needs the most discussion. Here's a starting point:

```typescript
import { solanaKit, defineProgram, u64, bool, pubKey } from '@solana-kit/sdk'

const counter = defineProgram({
  id: 'CoUnTeR1111111111111111111111111111111111111',
  name: 'counter',

  accounts: {
    counter: {
      // PDA seeds — the library uses this for deriveAddress() and account fetching
      seeds: ['counter', '{authority}'],
      fields: {
        count: u64,
        authority: pubKey,
        isActive: bool,
      },
    },
  },

  instructions: {
    initialize: {
      accounts: {
        counter: { writable: true, pda: true },
        authority: { signer: true, writable: true },
      },
      args: { initialValue: u64 },
    },
    increment: {
      accounts: {
        counter: { writable: true },
        authority: { signer: true },
      },
      args: { amount: u64 },
    },
    close: {
      accounts: {
        counter: { writable: true, closeTo: 'authority' },
        authority: { signer: true, writable: true },
      },
      args: {},
    },
  },
})
```

