## 6. Testing

No special test runner. Use whatever you already use — `node:test`, `vitest`, `jest`.

```typescript
import { describe, test, equal, throws } from 'your-test-runner'
import { testKit, defineProgram, u64, bool, pubKey } from '@solana-kit/sdk'

// testKit() creates an in-process Solana VM (LiteSVM under the hood)
// No validator startup. Milliseconds per test.

const counter = defineProgram({ /* ... */ })

describe('counter program', () => {
  test('initialize and increment', async () => {
    const kit = testKit({ programs: { counter } })

    const authority = kit.payer
    const addr = counter.accounts.counter.derive({ authority })

    await kit.execute(
      counter.instructions.initialize({
        counter: addr, authority, initialValue: 42n,
      })
    )

    const account = await kit.fetchAccount(counter.accounts.counter, addr)
    equal(account.count, 42n)

    await kit.execute(
      counter.instructions.increment({
        counter: addr, authority, amount: 10n,
      })
    )

    const updated = await kit.fetchAccount(counter.accounts.counter, addr)
    equal(updated.count, 52n)
  })

  test('non-authority cannot increment', async () => {
    const kit = testKit({ programs: { counter } })
    const stranger = await kit.createAccount() // funded test account

    const addr = counter.accounts.counter.derive({ authority: kit.payer })
    await kit.execute(
      counter.instructions.initialize({
        counter: addr, authority: kit.payer, initialValue: 0n,
      })
    )

    await throws(() =>
      kit.execute(
        counter.instructions.increment({
          counter: addr, authority: stranger, amount: 1n,
        })
      )
    )
  })
})
```

