  // Step 1
  token.createMint({ decimals: 9, authority: payer }),

  // Step 2 uses result from step 1
  (step1) => token.createAssociatedTokenAccount({ owner: payer, mint: step1.mint }),

  // Step 3 uses results from steps 1 and 2
