const ts = require('typescript');

// ============================================================
// PROOF OF CONCEPT: TypeScript → Anchor Rust Transpiler
// Tests whether we can actually convert function-body logic
// ============================================================

// The input: a logic function as a string
const logicSource = `
({ counter, authority }, { amount }) => {
  require(authority === counter.authority)
  require(counter.isActive)
  counter.count += amount
}
`;

// Parse it
const sf = ts.createSourceFile('logic.ts', `const _ = ${logicSource}`, ts.ScriptTarget.Latest, true);

// Find the arrow function
let arrowFn = null;
ts.forEachChild(sf, node => {
  if (ts.isVariableDeclaration(node) && node.initializer) {
    arrowFn = node.initializer;
  }
});

// === THE TRANSPILER ===

function transpileExpression(node, ctx) {
  switch (node.kind) {
    case ts.SyntaxKind.Identifier:
      return transpileIdentifier(node, ctx);

    case ts.SyntaxKind.PropertyAccessExpression:
      return transpilePropertyAccess(node, ctx);

    case ts.SyntaxKind.BinaryExpression:
      return transpileBinary(node, ctx);

    case ts.SyntaxKind.CallExpression:
      return transpileCall(node, ctx);

    case ts.SyntaxKind.PrefixUnaryExpression:
      return transpilePrefixUnary(node, ctx);

    case ts.SyntaxKind.BigIntLiteral:
      return node.text.replace(/n$/, '');

    case ts.SyntaxKind.TrueKeyword:
      return 'true';

    case ts.SyntaxKind.FalseKeyword:
      return 'false';

    case ts.SyntaxKind.StringLiteral:
      return `"${node.text}"`;

    default:
      return `/* TODO: ${ts.SyntaxKind[node.kind]} */`;
  }
}

function transpileIdentifier(node, ctx) {
  const name = node.text;
  // Check if it's an account or arg name
  if (ctx.accounts.includes(name)) {
    if (ctx.signers.includes(name)) return name; // signer binding
    return name;
  }
  return name;
}

function transpilePropertyAccess(node, ctx) {
  const obj = transpileExpression(node.expression, ctx);
  const prop = node.name.text;

  // ctx.prop → prop (strip ctx prefix for destructured params)
  // counter.authority → counter.authority
  return `${obj}.${toSnakeCase(prop)}`;
}

function toSnakeCase(str) {
  return str.replace(/([A-Z])/g, '_$1').toLowerCase();
}

function transpileBinary(node, ctx) {
  const left = transpileExpression(node.left, ctx);
  const right = transpileExpression(node.right, ctx);
  const op = ts.SyntaxKind[node.operatorToken.kind];

  const opMap = {
    'FirstAssignment': '=',
    'FirstCompoundAssignment': node.operatorToken.getText(),
    'EqualsEqualsEqualsToken': '==',
    'ExclamationEqualsEqualsToken': '!=',
    'GreaterThanToken': '>',
    'LessThanToken': '<',
    'GreaterThanEqualsToken': '>=',
    'LessThanEqualsToken': '<=',
    'PlusToken': '+',
    'MinusToken': '-',
    'AsteriskToken': '*',
    'SlashToken': '/',
    'PercentToken': '%',
    'AmpersandAmpersandToken': '&&',
    'BarBarToken': '||',
  };

  const rustOp = opMap[op] || node.operatorToken.getText();
  return `${left} ${rustOp} ${right}`;
}

function transpileCall(node, ctx) {
  // require(expr) → require!(expr);
  if (ts.isIdentifier(node.expression) && node.expression.text === 'require') {
    const arg = transpileExpression(node.arguments[0], ctx);
    return `require!(${arg})`;
  }

  // ctx.token.transfer({...}) → CPI call
  if (ts.isPropertyAccessExpression(node.expression)) {
    const method = node.expression.name.text;
    const objExpr = node.expression.expression;

    // Handle CPI calls like tokenProgram.transfer({...})
    if (ts.isPropertyAccessExpression(objExpr)) {
      const cpiProgram = objExpr.expression.text;
      const cpiMethod = objExpr.name.text;

      // Hmm, this is nested. Let's handle it differently.
    }

    // Simple: method(args)
    const args = node.arguments.map(a => transpileExpression(a, ctx));
    return `${transpileExpression(node.expression, ctx)}(${args.join(', ')})`;
  }

