const ts = require('typescript');

// ============================================================
// PROOF OF CONCEPT: Parse-time reference validation
// Walk the function body, check every identifier against an allowlist
// ============================================================

const testCode = `
import { readFileSync } from 'fs';  // ← Should be caught

const counter_count = 42n;  // ← local variable, allowed

({ counter, authority, tokenProgram }, { amount }) => {
  // Allowed: account fields, args, builtins
  require(authority === counter.authority);  // ✅
  counter.count += amount;                   // ✅
  const fee = amount * 10n / 100n;           // ✅ local variable
  token.transfer({ from: counter, to: counter, amount });  // ✅ CPI
  log("Fee: {}", fee);                       // ✅ log
  emit("Event", { amount });                 // ✅ emit

  // NOT allowed: globals, imports, unsupported APIs
  Math.random();                // ❌ Math is not available
  JSON.stringify(counter);      // ❌ JSON is not available
  new Date();                   // ❌ Date is not available
  console.log("hello");         // ❌ console is not available
  fetch("https://...");         // ❌ fetch is not available
  readFileSync("./data");       // ❌ imported module not available
  setTimeout(() => {}, 1000);   // ❌ setTimeout not available
  Promise.resolve(42);          // ❌ Promise not available

  // Allowed: escape hatch
  rust\`custom_rust_code()\`;    // ✅ tagged template escape hatch
}
`;

const sf = ts.createSourceFile('test.ts', testCode, ts.ScriptTarget.Latest, true);

// The allowlist
const ALLOWED_GLOBALS = new Set([
  // Our builtins
  'require', 'log', 'emit',
  // Our CPI namespaces
  'token', 'system', 'ata', 'token2022',
  // Our helpers
  'sol', 'rust', 'crypto',
  // JS literals and operators (handled by AST, not identifiers)
  'true', 'false', 'undefined', 'null',
  // Math constants that we provide
  'Infinity', 'NaN',
]);

// Track defined names (parameters, locals, imports we allow)
const definedNames = new Set();

// Collect parameter names
function collectBindings(node) {
  if (ts.isIdentifier(node)) {
    definedNames.add(node.text);
  } else if (ts.isObjectBindingPattern(node)) {
    node.elements.forEach(e => collectBindings(e.name));
  } else if (ts.isArrayBindingPattern(node)) {
    node.elements.forEach(e => {
      if (ts.isBindingElement(e)) collectBindings(e.name);
    });
  }
}

// Find the arrow function
let arrowFn = null;
ts.forEachChild(sf, node => {
  // Handle imports
  if (ts.isImportDeclaration(node)) {
    // We don't add imported names to definedNames
    // (they'll be caught as unsupported)
  }
  // Handle variable declarations at top level
  if (ts.isVariableStatement(node)) {
    // Only add if it's NOT an import
    node.declarationList.declarations.forEach(d => {
      if (d.name && ts.isIdentifier(d.name)) {
        definedNames.add(d.name.text);
      }
    });
  }
  // Find the arrow function
  if (ts.isExpressionStatement(node)) {
    const expr = node.expression;
    if (ts.isArrowFunction(expr)) {
      arrowFn = expr;
    }
    // Might be wrapped in parentheses
    if (ts.isParenthesizedExpression(expr) && ts.isArrowFunction(expr.expression)) {
      arrowFn = expr.expression;
    }
  }
});

if (arrowFn) {
  // Collect parameter bindings
  arrowFn.parameters.forEach(p => collectBindings(p.name));

  // Collect local variable declarations in the body
  function collectLocals(node) {
    if (ts.isVariableStatement(node)) {
      node.declarationList.declarations.forEach(d => {
        if (ts.isIdentifier(d.name)) definedNames.add(d.name.text);
      });
    }
    ts.forEachChild(node, collectLocals);
  }
  if (arrowFn.body) collectLocals(arrowFn.body);
}

// Now walk the function body and find all identifier references
const errors = [];

function checkReferences(node, inRustTemplate = false) {
  // If we're inside a rust`...` tagged template, skip validation
  if (ts.isTaggedTemplateExpression(node)) {
    if (ts.isIdentifier(node.tag) && node.tag.text === 'rust') {
      return; // Skip everything inside rust`...`
    }
  }

  if (ts.isIdentifier(node)) {
    const name = node.text;

    // Skip if it's a property name (not a reference)
    // Property names are the right side of dot access: counter.count (count is property)
    if (node.parent && ts.isPropertyAccessExpression(node.parent) && 
        node.parent.name === node) {
      return; // This is a property name, not a reference
    }

    // Skip if it's an object property key
    if (node.parent && ts.isPropertyAssignment(node.parent) && 
        node.parent.name === node) {
      return;
    }

    // Check if it's allowed
    if (!ALLOWED_GLOBALS.has(name) && !definedNames.has(name)) {
      // Check if it's a well-known disallowed global
      const disallowed = {
        'Math': 'Math is not available in Solana programs. Use our arithmetic operators or sol.checkedMul() for overflow protection.',
        'JSON': 'JSON is not available in Solana programs. Use sol.log() for debugging.',
        'Date': 'Date is not available. Use sol.timestamp() for current time or sol.slot() for current slot.',
        'console': 'console is not available. Use sol.log() to write to program logs.',
        'fetch': 'fetch/HTTP is not available in Solana programs. Programs cannot make network requests.',
        'setTimeout': 'setTimeout is not available. Solana programs are synchronous.',
        'setInterval': 'setInterval is not available. Solana programs are synchronous.',
        'Promise': 'Promises/async are not available. Solana programs are synchronous.',
        'Buffer': 'Buffer is not available. Use Uint8Array or sol.sha256() for hashing.',
        'process': 'process is not available. Solana programs don\'t have access to Node.js APIs.',
        'readFileSync': 'File system imports are not available. Solana programs can\'t read files.',
        'parseInt': 'parseInt is not available. Use direct bigint literals.',
        'parseFloat': 'parseFloat is not available. Use fixed-point arithmetic.',
        'Number': 'Number type is not available. Use u64/u128 (bigint) types.',
        'String': 'String constructor is not available. Use string literals directly.',
        'Array': 'Array constructor is not available. Use Vec fields in your account schema.',
        'Map': 'Map is not available. Use account fields for state storage.',
        'Set': 'Set is not available. Use Vec fields with sol.includes() checks.',
        'Object': 'Object constructor is not available. Solana accounts have fixed schemas.',
        'Error': 'Error is not available. Use require() with custom error strings.',
        'RegExp': 'RegExp is not available. Solana programs don\'t support pattern matching.',
        'atob': 'atob is not available. Use sol.fromBase64() for decoding.',
        'btoa': 'btoa is not available. Use sol.toBase64() for encoding.',
        'window': 'window is not available. Solana programs run on-chain, not in browsers.',
        'document': 'document is not available. Solana programs run on-chain.',
      };

      const hint = disallowed[name];
      if (hint) {
        errors.push({
          line: sf.getLineAndCharacterOfPosition(node.getStart()).line + 1,
          col: sf.getLineAndCharacterOfPosition(node.getStart()).character + 1,
          name,
          message: hint,
        });
      } else {
        errors.push({
          line: sf.getLineAndCharacterOfPosition(node.getStart()).line + 1,
          col: sf.getLineAndCharacterOfPosition(node.getStart()).character + 1,
          name,
          message: `'${name}' is not available in Solana program logic. Only account fields, arguments, and built-in functions (require, log, emit, token.*, system.*) are available.\n\nIf you need custom Rust code, use the escape hatch:\n  rust\`your_rust_code_here()\``,
        });
      }
    }
  }

  ts.forEachChild(node, child => checkReferences(child, inRustTemplate));
}

if (arrowFn && arrowFn.body) {
  checkReferences(arrowFn.body);
}

