// ============================================================
// COMPLETE AMM (Automated Market Maker) Program
// Written in our proposed @solana-kit/program syntax
//
// This exercises:
// - Multiple accounts with complex PDA seeds
// - Complex arithmetic (constant product formula, fees)
// - Multiple CPI calls per instruction
// - Both user-signed and PDA-signed token transfers
// - Token minting (LP tokens)
// - Events
// - Sysvars (timestamp)
// - Access control with custom errors
// - 7 instructions that compose together
// ============================================================

import { 
  program, u64, u8, u32, bool, pubkey,
  signer, writable, pda, tokenAccount, mint,
  tokenProgram, systemProgram, closeTo,
  vec, option
} from '@solana-kit/program'

export const amm = program('amm', 'AMMxPooL11111111111111111111111111111111111', {

  // ── Error definitions ──
  errors: {
    6000: 'Unauthorized',
    6001: 'PoolAlreadyExists',
    6002: 'PoolDoesNotExist',
    6003: 'InsufficientLiquidity',
    6004: 'SlippageExceeded',
    6005: 'InvalidAmount',
    6006: 'PoolExpired',
    6007: 'InvalidFeeBps',
    6008: 'MathOverflow',
  },

  // ── Account definitions ──
  accounts: {
    // Global config account — tracks total pools, admin
    config: {
      seeds: ['config'],
      admin: pubkey,
      totalPools: u64,
      feeBps: u64,           // Default fee in basis points (e.g., 30 = 0.3%)
      bump: u8,
    },

    // Pool account — one per trading pair
    pool: {
      seeds: ['pool', '{tokenAMint}', '{tokenBMint}'],
      tokenAMint: pubkey,
      tokenBMint: pubkey,
      tokenAReserve: pubkey,   // PDA token account for token A
      tokenBReserve: pubkey,   // PDA token account for token B
      lpMint: pubkey,          // LP token mint
      lpSupply: u64,           // Total LP tokens minted
      feeBps: u64,             // Pool-specific fee override
      createdAt: u64,          // Timestamp of creation
      admin: pubkey,           // Pool admin (can update fee)
      isActive: bool,
      totalVolumeA: u64,       // Lifetime volume tracking
      totalVolumeB: u64,
      bump: u8,
    },
  },

  // ── Events ──
  events: {
    PoolCreated: { pool: pubkey, tokenA: pubkey, tokenB: pubkey, lpMint: pubkey },
    LiquidityAdded: { pool: pubkey, amountA: u64, amountB: u64, lpTokens: u64 },
    LiquidityRemoved: { pool: pubkey, amountA: u64, amountB: u64, lpTokens: u64 },
    SwapExecuted: { pool: pubkey, amountIn: u64, amountOut: u64, fee: u64, direction: u8 },
    FeeUpdated: { pool: pubkey, newFeeBps: u64 },
  },

  // ── Instructions ──
  instructions: {

    // ─────────────────────────────────────
    // 1. Initialize the global config
    // ─────────────────────────────────────
    initializeConfig: {
      accounts: {
        config: [pda, writable],
        admin: [signer, writable],
        systemProgram: [systemProgram],
      },
      logic: ({ config, admin }, {}) => {
        config.admin = admin
        config.totalPools = 0n
        config.feeBps = 30n   // Default 0.3% fee
      },
    },

    // ─────────────────────────────────────
    // 2. Create a new trading pool
    // ─────────────────────────────────────
    createPool: {
      accounts: {
        config: [writable],
        pool: [pda, writable],
        tokenAMint: [mint],
        tokenBMint: [mint],
        lpMint: [pda, writable],            // PDA that owns the LP mint
        tokenAReserve: [pda, writable],     // PDA token account for A
        tokenBReserve: [pda, writable],     // PDA token account for B
        creator: [signer, writable],
        tokenProgram: [tokenProgram],
        systemProgram: [systemProgram],
      },
      args: { feeBps: u64 },
      logic: ({ config, pool, tokenAMint, tokenBMint, lpMint, tokenAReserve, tokenBReserve, creator, tokenProgram }, { feeBps }) => {
        // Access control
        require(creator === config.admin, 'Unauthorized')

        // Validate fee
        require(feeBps <= 1000n, 'InvalidFeeBps')  // Max 10%

        // Initialize pool
        pool.tokenAMint = tokenAMint
        pool.tokenBMint = tokenBMint
        pool.tokenAReserve = tokenAReserve
        pool.tokenBReserve = tokenBReserve
        pool.lpMint = lpMint
        pool.lpSupply = 0n
        pool.feeBps = feeBps
        pool.createdAt = sol.timestamp()
        pool.admin = creator
        pool.isActive = true
        pool.totalVolumeA = 0n
        pool.totalVolumeB = 0n

        // Update config
        config.totalPools += 1n

        emit('PoolCreated', { pool, tokenA: tokenAMint, tokenB: tokenBMint, lpMint })
      },
    },

    // ─────────────────────────────────────
    // 3. Add liquidity to a pool
    // ─────────────────────────────────────
    addLiquidity: {
      accounts: {
        pool: [writable],
        tokenAReserve: [tokenAccount(tokenAMint), writable],
        tokenBReserve: [tokenAccount(tokenBMint), writable],
        lpMint: [mint, writable],
        depositorTokenA: [tokenAccount(tokenAMint), writable],
        depositorTokenB: [tokenAccount(tokenBMint), writable],
        depositorLp: [tokenAccount(lpMint), writable],
        depositor: [signer, writable],
        tokenProgram: [tokenProgram],
      },
      args: { amountA: u64, amountB: u64, minLpTokens: u64 },
      logic: ({ pool, tokenAReserve, tokenBReserve, lpMint, depositorTokenA, depositorTokenB, depositorLp, depositor, tokenProgram }, { amountA, amountB, minLpTokens }) => {
        require(pool.isActive, 'PoolDoesNotExist')
        require(amountA > 0n, 'InvalidAmount')
        require(amountB > 0n, 'InvalidAmount')

        // Calculate LP tokens to mint
        let lpTokens: u64

        if (pool.lpSupply === 0n) {
          // First deposit: LP tokens = sqrt(amountA * amountB)
          // We use a simplified formula for the first deposit
          lpTokens = (amountA * amountB) / 1000000n
          require(lpTokens > 0n, 'InvalidAmount')
        } else {
          // Subsequent deposits: proportional to existing liquidity
          const lpFromA = (amountA * pool.lpSupply) / tokenAReserve.amount
          const lpFromB = (amountB * pool.lpSupply) / tokenBReserve.amount
          lpTokens = lpFromA < lpFromB ? lpFromA : lpFromB
        }

        // Slippage protection
        require(lpTokens >= minLpTokens, 'SlippageExceeded')

        // Transfer token A from depositor to pool reserve
        token.transfer({
          from: depositorTokenA,
          to: tokenAReserve,
          authority: depositor,
          amount: amountA,
        })

        // Transfer token B from depositor to pool reserve
        token.transfer({
          from: depositorTokenB,
          to: tokenBReserve,
          authority: depositor,
          amount: amountB,
        })

        // Mint LP tokens to depositor (PDA-signed)
        token.mintTo({
          mint: lpMint,
          destination: depositorLp,
          authority: pool,  // PDA signer — auto-detected
          amount: lpTokens,
        })

        // Update pool state
        pool.lpSupply += lpTokens
        pool.totalVolumeA += amountA
        pool.totalVolumeB += amountB

        emit('LiquidityAdded', { pool, amountA, amountB, lpTokens })
      },
    },

    // ─────────────────────────────────────
    // 4. Remove liquidity from a pool
    // ─────────────────────────────────────
    removeLiquidity: {
      accounts: {
        pool: [writable],
        tokenAReserve: [tokenAccount(tokenAMint), writable],
        tokenBReserve: [tokenAccount(tokenBMint), writable],
        lpMint: [mint, writable],
        withdrawerTokenA: [tokenAccount(tokenAMint), writable],
        withdrawerTokenB: [tokenAccount(tokenBMint), writable],
        withdrawerLp: [tokenAccount(lpMint), writable],
        withdrawer: [signer, writable],
        tokenProgram: [tokenProgram],
      },
      args: { lpTokens: u64, minAmountA: u64, minAmountB: u64 },
      logic: ({ pool, tokenAReserve, tokenBReserve, lpMint, withdrawerTokenA, withdrawerTokenB, withdrawerLp, withdrawer, tokenProgram }, { lpTokens, minAmountA, minAmountB }) => {
        require(pool.isActive, 'PoolDoesNotExist')
        require(lpTokens > 0n, 'InvalidAmount')
        require(pool.lpSupply > 0n, 'InsufficientLiquidity')

        // Calculate proportional amounts
        const amountA = (lpTokens * tokenAReserve.amount) / pool.lpSupply
        const amountB = (lpTokens * tokenBReserve.amount) / pool.lpSupply

        // Slippage protection
        require(amountA >= minAmountA, 'SlippageExceeded')
        require(amountB >= minAmountB, 'SlippageExceeded')

        // Burn LP tokens from withdrawer (PDA-signed)
        token.burn({
          account: withdrawerLp,
          mint: lpMint,
          authority: withdrawer,
          amount: lpTokens,
        })

        // Transfer token A from pool reserve to withdrawer (PDA-signed)
        token.transfer({
          from: tokenAReserve,
          to: withdrawerTokenA,
          authority: pool,  // PDA signer
          amount: amountA,
        })

        // Transfer token B from pool reserve to withdrawer (PDA-signed)
        token.transfer({
          from: tokenBReserve,
          to: withdrawerTokenB,
          authority: pool,  // PDA signer
          amount: amountB,
        })

        // Update pool state
        pool.lpSupply -= lpTokens

        emit('LiquidityRemoved', { pool, amountA, amountB, lpTokens })
      },
    },

    // ─────────────────────────────────────
    // 5. Swap token A → token B
    // ─────────────────────────────────────
    swapAForB: {
      accounts: {
        pool: [writable],
        tokenAReserve: [tokenAccount(tokenAMint), writable],
        tokenBReserve: [tokenAccount(tokenBMint), writable],
        traderTokenA: [tokenAccount(tokenAMint), writable],
        traderTokenB: [tokenAccount(tokenBMint), writable],
        trader: [signer, writable],
        tokenProgram: [tokenProgram],
      },
      args: { amountIn: u64, minimumAmountOut: u64 },
      logic: ({ pool, tokenAReserve, tokenBReserve, traderTokenA, traderTokenB, trader, tokenProgram }, { amountIn, minimumAmountOut }) => {
        require(pool.isActive, 'PoolDoesNotExist')
        require(amountIn > 0n, 'InvalidAmount')

        // Read current reserves
        const reserveIn = tokenAReserve.amount
        const reserveOut = tokenBReserve.amount

        // Calculate fee
        const fee = (amountIn * pool.feeBps) / 10000n

        // Constant product formula: x * y = k
        // amountOut = (netIn * reserveOut) / (reserveIn + netIn)
        const netIn = amountIn - fee
        const amountOut = (netIn * reserveOut) / (reserveIn + netIn)

        // Slippage protection
        require(amountOut >= minimumAmountOut, 'SlippageExceeded')

        // Transfer token A from trader to pool
        token.transfer({
          from: traderTokenA,
          to: tokenAReserve,
          authority: trader,
          amount: amountIn,
        })

        // Transfer token B from pool to trader (PDA-signed)
        token.transfer({
          from: tokenBReserve,
          to: traderTokenB,
          authority: pool,  // PDA signer
          amount: amountOut,
        })

        // Update pool state
        pool.totalVolumeA += amountIn
        pool.totalVolumeB += amountOut

        emit('SwapExecuted', { pool, amountIn, amountOut, fee, direction: 0 })
      },
    },

    // ─────────────────────────────────────
    // 6. Swap token B → token A
    // ─────────────────────────────────────
    swapBForA: {
      accounts: {
        pool: [writable],
        tokenAReserve: [tokenAccount(tokenAMint), writable],
        tokenBReserve: [tokenAccount(tokenBMint), writable],
        traderTokenA: [tokenAccount(tokenAMint), writable],
        traderTokenB: [tokenAccount(tokenBMint), writable],
        trader: [signer, writable],
        tokenProgram: [tokenProgram],
      },
      args: { amountIn: u64, minimumAmountOut: u64 },
      logic: ({ pool, tokenAReserve, tokenBReserve, traderTokenA, traderTokenB, trader, tokenProgram }, { amountIn, minimumAmountOut }) => {
        require(pool.isActive, 'PoolDoesNotExist')
        require(amountIn > 0n, 'InvalidAmount')

        // Read current reserves (B is input, A is output)
        const reserveIn = tokenBReserve.amount
        const reserveOut = tokenAReserve.amount

        // Calculate fee
        const fee = (amountIn * pool.feeBps) / 10000n

        // Constant product formula
        const netIn = amountIn - fee
        const amountOut = (netIn * reserveOut) / (reserveIn + netIn)

        // Slippage protection
        require(amountOut >= minimumAmountOut, 'SlippageExceeded')

        // Transfer token B from trader to pool
        token.transfer({
          from: traderTokenB,
          to: tokenBReserve,
          authority: trader,
          amount: amountIn,
        })

        // Transfer token A from pool to trader (PDA-signed)
        token.transfer({
          from: tokenAReserve,
          to: traderTokenA,
          authority: pool,  // PDA signer
          amount: amountOut,
        })

        // Update pool state
        pool.totalVolumeA += amountOut
        pool.totalVolumeB += amountIn

        emit('SwapExecuted', { pool, amountIn, amountOut, fee, direction: 1 })
      },
    },

    // ─────────────────────────────────────
    // 7. Update pool fee (admin only)
    // ─────────────────────────────────────
    updateFee: {
      accounts: {
        pool: [writable],
        admin: [signer],
      },
      args: { newFeeBps: u64 },
      logic: ({ pool, admin }, { newFeeBps }) => {
        require(admin === pool.admin, 'Unauthorized')
        require(newFeeBps <= 1000n, 'InvalidFeeBps')  // Max 10%

        const oldFee = pool.feeBps
        pool.feeBps = newFeeBps

        emit('FeeUpdated', { pool, newFeeBps })
        log('Fee updated from {}bps to {}bps', oldFee, newFeeBps)
      },
    },
  },
})
