// ============================================================
// GENERATED OUTPUT #2: The Client SDK usage
// How a developer uses the AMM program from their app
// The same `amm` definition that was used for compilation
// is also the typed client SDK — zero additional code.
// ============================================================

import { createClient } from '@solana-kit/sdk'
import { amm } from './programs/amm'

// ── Setup ──

const client = createClient({
  cluster: 'devnet',
  payer: './keypair.json',
  programs: { amm },  // Same object used for compilation = typed client
})

const payer = client.payer

// ── PDA derivation (from account seed definitions) ──

// Config PDA — seeds: ['config']
const configAddr = amm.accounts.config.derive()

// Pool PDA — seeds: ['pool', '{tokenAMint}', '{tokenBMint}']
const SOL_MINT = 'So11111111111111111111111111111111111111112'
const USDC_MINT = 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v'
const poolAddr = amm.accounts.pool.derive({
  tokenAMint: SOL_MINT,
  tokenBMint: USDC_MINT,
})

// ── 1. Initialize config (admin only) ──

await client.amm.initializeConfig({
  config: configAddr,
  admin: payer,
})

// ── 2. Create a SOL/USDC pool ──

await client.amm.createPool({
  config: configAddr,
  pool: poolAddr,
  tokenAMint: SOL_MINT,
  tokenBMint: USDC_MINT,
  creator: payer,
  feeBps: 30n,  // 0.3% fee
})

// ── 3. Add liquidity (deposit 10 SOL + 1000 USDC) ──

const depositorTokenA = client.token.getAssociatedTokenAddress({ owner: payer, mint: SOL_MINT })
const depositorTokenB = client.token.getAssociatedTokenAddress({ owner: payer, mint: USDC_MINT })

// We need to know the reserve and LP addresses — derived from pool
const poolData = await client.amm.fetch(poolAddr)

await client.amm.addLiquidity({
  pool: poolAddr,
  tokenAReserve: poolData.tokenAReserve,
  tokenBReserve: poolData.tokenBReserve,
  lpMint: poolData.lpMint,
  depositorTokenA,
  depositorTokenB,
  depositorLp: client.token.getAssociatedTokenAddress({ owner: payer, mint: poolData.lpMint }),
  depositor: payer,
  amountA: 10_000_000_000n,     // 10 SOL
  amountB: 1_000_000_000n,      // 1000 USDC (6 decimals)
  minLpTokens: 0n,              // Accept any amount (dangerous in production!)
})

// ── 4. Swap SOL → USDC ──

// Get the pool state to see current reserves
const pool = await client.amm.fetch(poolAddr)
console.log(`Pool reserves: ${pool.totalVolumeA} SOL, ${pool.totalVolumeB} USDC`)
console.log(`LP supply: ${pool.lpSupply}`)
console.log(`Fee: ${pool.feeBps}bps`)

// Calculate expected output (can also be done client-side for preview)
const amountIn = 1_000_000_000n // 1 SOL
const fee = (amountIn * pool.feeBps) / 10000n
const netIn = amountIn - fee
const expectedOut = (netIn * /* reserveB */ 1_000_000_000n) / (/* reserveA */ 10_000_000_000n + netIn)
console.log(`Expected output: ~${expectedOut} USDC`)

// Execute the swap
await client.amm.swapAForB({
  pool: poolAddr,
  tokenAReserve: pool.tokenAReserve,
  tokenBReserve: pool.tokenBReserve,
  traderTokenA: client.token.getAssociatedTokenAddress({ owner: payer, mint: SOL_MINT }),
  traderTokenB: client.token.getAssociatedTokenAddress({ owner: payer, mint: USDC_MINT }),
  trader: payer,
  amountIn: 1_000_000_000n,             // 1 SOL
  minimumAmountOut: 90_000_000n,         // At least 90 USDC (slippage protection)
})

// ── 5. Check balances after swap ──

const solBalance = await client.token.getBalance({
  owner: payer,
  mint: SOL_MINT,
})

const usdcBalance = await client.token.getBalance({
  owner: payer,
  mint: USDC_MINT,
})

console.log(`SOL: ${solBalance}, USDC: ${usdcBalance}`)

