# Final verification: count every operation type used across all 7 instructions
cd /tmp && node -e "
const ts = require('typescript');
const fs = require('fs');

const source = fs.readFileSync('/home/pow/projects/personal/hack/solana-hackathon/research/examples/amm-program.ts', 'utf8');
const sf = ts.createSourceFile('amm.ts', source, ts.ScriptTarget.Latest, true);

const operations = {
  'Field assignment': 0,
  'Compound +=': 0,
  'Compound -=': 0,
  'require()': 0,
  'require() with error': 0,
  'if/else': 0,
  'Local variable (const)': 0,
  'Local variable (let)': 0,
  'Ternary': 0,
  'token.transfer() (user-signed)': 0,
  'token.transfer() (PDA-signed)': 0,
  'token.mintTo()': 0,
  'token.burn()': 0,
  'emit()': 0,
  'log()': 0,
  'sol.timestamp()': 0,
  'Arithmetic (+)': 0,
  'Arithmetic (-)': 0,
  'Arithmetic (*)': 0,
  'Arithmetic (/)': 0,
  'Comparison (===)': 0,
  'Comparison (>)': 0,
  'Comparison (>=)': 0,
  'Comparison (<)': 0,
  'Comparison (<=)': 0,
};

function countOps(node) {
  // Field assignments
  if (ts.isBinaryExpression(node) && node.operatorToken.kind === ts.SyntaxKind.FirstAssignment) {
    if (ts.isPropertyAccessExpression(node.left)) {
      operations['Field assignment']++;
    }
  }

  // Compound assignments
  if (ts.isBinaryExpression(node)) {
    if (node.operatorToken.kind === ts.SyntaxKind.PlusEqualsToken) operations['Compound +=']++;
    if (node.operatorToken.kind === ts.SyntaxKind.MinusEqualsToken) operations['Compound -=']++;
  }

  // require calls
  if (ts.isCallExpression(node) && ts.isIdentifier(node.expression) && node.expression.text === 'require') {
    operations['require()']++;
    if (node.arguments.length > 1) operations['require() with error']++;
  }

  // if/else
  if (ts.isIfStatement(node)) operations['if/else']++;

  // Ternary
  if (ts.isConditionalExpression(node)) operations['Ternary']++;

  // Variables
  if (ts.isVariableDeclaration(node)) {
    if (node.parent && node.parent.parent) {
      const list = node.parent;
      if (list.flags & ts.NodeFlags.Const) {
        operations['Local variable (const)']++;
      } else {
        operations['Local variable (let)']++;
      }
    }
  }

  // CPI calls
  if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
    const method = node.expression.name.text;
    const obj = node.expression.expression;

    if (ts.isIdentifier(obj)) {
      if (obj.text === 'token') {
        if (method === 'transfer') {
          // Check if PDA-signed by looking at authority arg
          const args = node.arguments[0];
          if (ts.isObjectLiteralExpression(args)) {
            const authProp = args.properties.find(p => 
              ts.isPropertyAssignment(p) && p.name.getText() === 'authority');
            if (authProp && ts.isPropertyAssignment(authProp)) {
              const authName = authProp.initializer.getText();
              if (['pool', 'escrow', 'config'].includes(authName)) {
                operations['token.transfer() (PDA-signed)']++;
              } else {
                operations['token.transfer() (user-signed)']++;
              }
            }
          }
        }
        if (method === 'mintTo') operations['token.mintTo()']++;
        if (method === 'burn') operations['token.burn()']++;
      }
      if (obj.text === 'emit') operations['emit()']++;
      if (obj.text === 'log') operations['log()']++;
      if (obj.text === 'sol' && method === 'timestamp') operations['sol.timestamp()']++;
    }
  }

  // Arithmetic
  if (ts.isBinaryExpression(node)) {
    if (node.operatorToken.kind === ts.SyntaxKind.PlusToken) operations['Arithmetic (+)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.MinusToken) operations['Arithmetic (-)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.AsteriskToken) operations['Arithmetic (*)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.SlashToken) operations['Arithmetic (/)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.EqualsEqualsEqualsToken) operations['Comparison (===)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.GreaterThanToken) operations['Comparison (>)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.GreaterThanEqualsToken) operations['Comparison (>=)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.LessThanToken) operations['Comparison (<)']++;
    if (node.operatorToken.kind === ts.SyntaxKind.LessThanEqualsToken) operations['Comparison (<=)']++;
  }

  ts.forEachChild(node, countOps);
}

countOps(sf);

