// ============================================================
// THE CLEANEST POSSIBLE SYNTAX
// Inspired by: Zod (schemas), tRPC (procedures), Drizzle (tables)
// ============================================================

import { program, account, instruction, u64, u8, bool, pubkey, signer, token, sol } from '@solana-kit/program'

// ── ACCOUNTS: Like Zod schemas ──

// Just fields. Clean. No nesting.
const Config = account({
  admin: pubkey,
  totalPools: u64,
  feeBps: u64,
  bump: u8,
}).seeds('config')

const Pool = account({
  tokenAMint: pubkey,
  tokenBMint: pubkey,
  tokenAReserve: pubkey,
  tokenBReserve: pubkey,
  lpMint: pubkey,
  lpSupply: u64,
  feeBps: u64,
  createdAt: u64,
  admin: pubkey,
  isActive: bool,
  totalVolumeA: u64,
  totalVolumeB: u64,
  bump: u8,
}).seeds('pool', '{tokenAMint}', '{tokenBMint}')

// ── INSTRUCTIONS: Like tRPC procedures ──

export const amm = program('amm', 'AMMxxx...', {

  // Instruction 1: Just a run function.
  // Account constraints are specified inline — minimal ceremony.
  initializeConfig: instruction(
    { config: Config.init(), admin: signer() },
    ({ config, admin }) => {
      config.admin = admin
      config.totalPools = 0n
      config.feeBps = 30n
    }
  ),

  // Instruction 2: With args.
  // Args come after accounts, before the handler.
  createPool: instruction(
    { 
      config: Config,
      pool: Pool.init(),
      creator: signer(),
    },
    { feeBps: u64 },
    ({ pool, creator }, { feeBps }) => {
      require(creator === config.admin, 'Unauthorized')
      require(feeBps <= 1000n, 'InvalidFeeBps')

      pool.tokenAMint = tokenAMint  // ← Wait, where does tokenAMint come from?
      // PROBLEM: We need to pass accounts that aren't "our" accounts (external mints, token accounts)
      // These can't be typed by our account definitions
    }
  ),

  // This reveals a design issue: not all accounts map to our account types.
  // Token accounts, mints, sysvars — these are EXTERNAL.
  // We need a way to declare them too.
})

// ── THE CORE DESIGN TENSION ──
//
// In a Solana instruction, accounts fall into categories:
//
// 1. YOUR accounts (defined by account()) — typed, with fields
// 2. Signers — just a public key
// 3. Token accounts — have .amount, .owner, .mint, .decimals
// 4. Mints — have .supply, .authority, .decimals
// 5. Programs — token program, system program, etc.
// 6. Sysvars — clock, rent, etc.
//
// The instruction needs to declare ALL of these.
// But only category 1 has user-defined types.
// Categories 2-6 are standard Solana types.
//
// The cleanest API would make category 1 feel special (your types)
// and categories 2-6 feel standard (built-in types).
TSEOF

