const ts = require('typescript');
const fs = require('fs');
const src = fs.readFileSync('simplest-syntax.ts', 'utf8');
const sf = ts.createSourceFile('test.ts', src, ts.ScriptTarget.Latest, true);

// Check for syntax errors
