      ts.isIdentifier(node.name) && node.name.text === 'run' &&
      ts.isArrowFunction(node.initializer)) {
    runFunctions++;
    const params = node.initializer.parameters;
    console.log('run() params:', params.length, 
      params.map(p => p.getText().substring(0, 40)));
  }
  ts.forEachChild(node, findRun);
}
findRun(sf);
console.log('run() functions found:', runFunctions);
