// ============================================================
// AMM (Automated Market Maker) — Complete Program
//
// Written in @solana-kit/program syntax
// This file defines the on-chain program AND serves as the
// typed client SDK — zero additional code needed.
//
// What this exercises:
// - Multiple accounts with PDA seeds
// - Complex arithmetic (constant product formula, fees)
// - Multiple CPI calls per instruction
// - User-signed and PDA-signed token transfers
// - Token minting and burning (LP tokens)
// - Events and logging
// - Sysvars (timestamp)
// - Access control with custom errors
// - 7 instructions that compose together
// ============================================================

import {
  program, account, ix,
  u64, u8, bool, pubkey,
  p, token, sol, emit, log, require,
} from '@solana-kit/program'


// ══════════════════════════════════════════
// ACCOUNTS — Like Zod schemas
// ══════════════════════════════════════════

const Config = account({
  admin: pubkey,
  totalPools: u64,
  feeBps: u64,
  bump: u8,
}).seeds('config')

const Pool = account({
  tokenAMint: pubkey,
  tokenBMint: pubkey,
  tokenAReserve: pubkey,
  tokenBReserve: pubkey,
  lpMint: pubkey,
  lpSupply: u64,
  feeBps: u64,
  createdAt: u64,
  admin: pubkey,
  isActive: bool,
  totalVolumeA: u64,
  totalVolumeB: u64,
  bump: u8,
}).seeds('pool', '{tokenAMint}', '{tokenBMint}')


// ══════════════════════════════════════════
// ERRORS
// ══════════════════════════════════════════

const errors = {
  Unauthorized: 'Caller is not authorized',
  PoolDoesNotExist: 'Pool does not exist or is inactive',
  InsufficientLiquidity: 'Not enough liquidity in the pool',
  SlippageExceeded: 'Output amount below minimum (slippage)',
  InvalidAmount: 'Amount must be greater than zero',
  InvalidFeeBps: 'Fee must be between 0 and 1000 basis points',
}


// ══════════════════════════════════════════
// PROGRAM — Flat instruction map
// ══════════════════════════════════════════

export const amm = program('amm', 'AMMxPooL11111111111111111111111111111111111', errors, {

  // ── 1. Initialize the global config ──
  initializeConfig: ix({
    accounts: {
      config: p.init(Config),
      admin: p.signer(),
    },
    run: ({ config, admin }) => {
      config.admin = admin
      config.totalPools = 0n
      config.feeBps = 30n
    },
  }),

  // ── 2. Create a new trading pool ──
  createPool: ix({
    accounts: {
      config: Config,
      pool: p.init(Pool),
      tokenAMint: p.mint(),
      tokenBMint: p.mint(),
      creator: p.signer(),
    },
    args: { feeBps: u64 },
    run: ({ config, pool, tokenAMint, tokenBMint, creator }, { feeBps }) => {
      require(creator === config.admin, 'Unauthorized')
      require(feeBps <= 1000n, 'InvalidFeeBps')

      pool.tokenAMint = tokenAMint
      pool.tokenBMint = tokenBMint
      pool.lpSupply = 0n
      pool.feeBps = feeBps
      pool.createdAt = sol.timestamp()
      pool.admin = creator
      pool.isActive = true
      pool.totalVolumeA = 0n
      pool.totalVolumeB = 0n

      config.totalPools += 1n

      emit('PoolCreated', { pool, tokenA: tokenAMint, tokenB: tokenBMint })
    },
  }),

  // ── 3. Add liquidity to a pool ──
  addLiquidity: ix({
    accounts: {
      pool: p.mut(Pool),
      tokenAReserve: p.tokenAccount('tokenAMint').mut(),
      tokenBReserve: p.tokenAccount('tokenBMint').mut(),
      lpMint: p.mint().mut(),
      depositorTokenA: p.tokenAccount('tokenAMint').mut(),
      depositorTokenB: p.tokenAccount('tokenBMint').mut(),
      depositorLp: p.tokenAccount('lpMint').mut(),
      depositor: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { amountA: u64, amountB: u64, minLpTokens: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, lpMint, depositorTokenA, depositorTokenB, depositorLp, depositor }, { amountA, amountB, minLpTokens }) => {
      require(pool.isActive, 'PoolDoesNotExist')
      require(amountA > 0n, 'InvalidAmount')
      require(amountB > 0n, 'InvalidAmount')

      let lpTokens = 0n

      if (pool.lpSupply === 0n) {
        // First deposit: LP tokens = geometric mean
        lpTokens = (amountA * amountB) / 1000000n
        require(lpTokens > 0n, 'InvalidAmount')
      } else {
        // Subsequent deposits: proportional to existing liquidity
        const lpFromA = (amountA * pool.lpSupply) / tokenAReserve.amount
        const lpFromB = (amountB * pool.lpSupply) / tokenBReserve.amount
        lpTokens = lpFromA < lpFromB ? lpFromA : lpFromB
      }

      require(lpTokens >= minLpTokens, 'SlippageExceeded')

      // Transfer both tokens from depositor to pool reserves
      token.transfer({ from: depositorTokenA, to: tokenAReserve, authority: depositor, amount: amountA })
      token.transfer({ from: depositorTokenB, to: tokenBReserve, authority: depositor, amount: amountB })

      // Mint LP tokens to depositor (PDA-signed — pool is the authority)
      token.mintTo({ mint: lpMint, to: depositorLp, authority: pool, amount: lpTokens })

      pool.lpSupply += lpTokens
      pool.totalVolumeA += amountA
      pool.totalVolumeB += amountB

      emit('LiquidityAdded', { pool, amountA, amountB, lpTokens })
    },
  }),

  // ── 4. Remove liquidity from a pool ──
  removeLiquidity: ix({
    accounts: {
      pool: p.mut(Pool),
      tokenAReserve: p.tokenAccount('tokenAMint').mut(),
      tokenBReserve: p.tokenAccount('tokenBMint').mut(),
      lpMint: p.mint().mut(),
      withdrawerTokenA: p.tokenAccount('tokenAMint').mut(),
      withdrawerTokenB: p.tokenAccount('tokenBMint').mut(),
      withdrawerLp: p.tokenAccount('lpMint').mut(),
      withdrawer: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { lpTokens: u64, minAmountA: u64, minAmountB: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, lpMint, withdrawerTokenA, withdrawerTokenB, withdrawerLp, withdrawer }, { lpTokens, minAmountA, minAmountB }) => {
      require(pool.isActive, 'PoolDoesNotExist')
      require(lpTokens > 0n, 'InvalidAmount')
      require(pool.lpSupply > 0n, 'InsufficientLiquidity')

      // Calculate proportional withdrawal
      const amountA = (lpTokens * tokenAReserve.amount) / pool.lpSupply
      const amountB = (lpTokens * tokenBReserve.amount) / pool.lpSupply

      require(amountA >= minAmountA, 'SlippageExceeded')
      require(amountB >= minAmountB, 'SlippageExceeded')

      // Burn the LP tokens
      token.burn({ from: withdrawerLp, mint: lpMint, authority: withdrawer, amount: lpTokens })

      // Transfer proportional amounts back (PDA-signed)
      token.transfer({ from: tokenAReserve, to: withdrawerTokenA, authority: pool, amount: amountA })
      token.transfer({ from: tokenBReserve, to: withdrawerTokenB, authority: pool, amount: amountB })

      pool.lpSupply -= lpTokens

      emit('LiquidityRemoved', { pool, amountA, amountB, lpTokens })
    },
  }),

  // ── 5. Swap token A → token B ──
  swapAForB: ix({
    accounts: {
      pool: p.mut(Pool),
      tokenAReserve: p.tokenAccount('tokenAMint').mut(),
      tokenBReserve: p.tokenAccount('tokenBMint').mut(),
      traderTokenA: p.tokenAccount('tokenAMint').mut(),
      traderTokenB: p.tokenAccount('tokenBMint').mut(),
      trader: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { amountIn: u64, minOut: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, traderTokenA, traderTokenB, trader }, { amountIn, minOut }) => {
      require(pool.isActive, 'PoolDoesNotExist')
      require(amountIn > 0n, 'InvalidAmount')

      // Constant product formula: x * y = k
      const fee = (amountIn * pool.feeBps) / 10000n
      const netIn = amountIn - fee
      const amountOut = (netIn * tokenBReserve.amount) / (tokenAReserve.amount + netIn)

      require(amountOut >= minOut, 'SlippageExceeded')

      // Transfer A from trader to pool (user-signed)
      token.transfer({ from: traderTokenA, to: tokenAReserve, authority: trader, amount: amountIn })

      // Transfer B from pool to trader (PDA-signed)
      token.transfer({ from: tokenBReserve, to: traderTokenB, authority: pool, amount: amountOut })

      pool.totalVolumeA += amountIn
      pool.totalVolumeB += amountOut

      emit('SwapExecuted', { pool, amountIn, amountOut, fee, direction: 0 })
    },
  }),

  // ── 6. Swap token B → token A ──
  swapBForA: ix({
    accounts: {
      pool: p.mut(Pool),
      tokenAReserve: p.tokenAccount('tokenAMint').mut(),
      tokenBReserve: p.tokenAccount('tokenBMint').mut(),
      traderTokenA: p.tokenAccount('tokenAMint').mut(),
      traderTokenB: p.tokenAccount('tokenBMint').mut(),
      trader: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { amountIn: u64, minOut: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, traderTokenA, traderTokenB, trader }, { amountIn, minOut }) => {
      require(pool.isActive, 'PoolDoesNotExist')
      require(amountIn > 0n, 'InvalidAmount')

      // Constant product formula (reversed reserves)
      const fee = (amountIn * pool.feeBps) / 10000n
      const netIn = amountIn - fee
      const amountOut = (netIn * tokenAReserve.amount) / (tokenBReserve.amount + netIn)

      require(amountOut >= minOut, 'SlippageExceeded')

      // Transfer B from trader to pool (user-signed)
      token.transfer({ from: traderTokenB, to: tokenBReserve, authority: trader, amount: amountIn })

      // Transfer A from pool to trader (PDA-signed)
      token.transfer({ from: tokenAReserve, to: traderTokenA, authority: pool, amount: amountOut })

      pool.totalVolumeA += amountOut
      pool.totalVolumeB += amountIn

      emit('SwapExecuted', { pool, amountIn, amountOut, fee, direction: 1 })
    },
  }),

  // ── 7. Update pool fee (admin only) ──
  updateFee: ix({
    accounts: {
      pool: p.mut(Pool),
      admin: p.signer(),
    },
    args: { newFeeBps: u64 },
    run: ({ pool, admin }, { newFeeBps }) => {
      require(admin === pool.admin, 'Unauthorized')
      require(newFeeBps <= 1000n, 'InvalidFeeBps')

      pool.feeBps = newFeeBps

      emit('FeeUpdated', { pool, newFeeBps })
      log('Fee updated to {}bps', newFeeBps)
    },
  }),
})

// ============================================================
// GENERATED OUTPUT: Anchor Rust code
// What our transpiler generates from amm-program.ts
// This is what gets compiled to sBPF and deployed on-chain.
// ============================================================

use anchor_lang::prelude::*;
use anchor_spl::token::{self, Token, TokenAccount, Mint, Transfer, MintTo, Burn};
use anchor_spl::associated_token::AssociatedToken;

declare_id!("AMMxPooL11111111111111111111111111111111111");

// ── Error codes ──

#[error_code]
pub enum AmmError {
    #[msg("Caller is not authorized")]
    Unauthorized,
    #[msg("Pool does not exist or is inactive")]
    PoolDoesNotExist,
    #[msg("Not enough liquidity in the pool")]
    InsufficientLiquidity,
    #[msg("Output amount below minimum (slippage)")]
    SlippageExceeded,
    #[msg("Amount must be greater than zero")]
    InvalidAmount,
    #[msg("Fee must be between 0 and 1000 basis points")]
    InvalidFeeBps,
}

// ── Events ──

#[event]
pub struct PoolCreated {
    pub pool: Pubkey,
    pub token_a: Pubkey,
    pub token_b: Pubkey,
}

#[event]
pub struct LiquidityAdded {
    pub pool: Pubkey,
    pub amount_a: u64,
    pub amount_b: u64,
    pub lp_tokens: u64,
}

#[event]
pub struct LiquidityRemoved {
    pub pool: Pubkey,
    pub amount_a: u64,
    pub amount_b: u64,
    pub lp_tokens: u64,
}

#[event]
pub struct SwapExecuted {
    pub pool: Pubkey,
    pub amount_in: u64,
    pub amount_out: u64,
    pub fee: u64,
    pub direction: u8,
}

#[event]
pub struct FeeUpdated {
    pub pool: Pubkey,
    pub new_fee_bps: u64,
}

// ── Account structs ──

#[account]
pub struct Config {
    pub admin: Pubkey,
    pub total_pools: u64,
    pub fee_bps: u64,
    pub bump: u8,
}
// Space: 8 (discriminator) + 32 + 8 + 8 + 1 = 57

#[account]
pub struct Pool {
    pub token_a_mint: Pubkey,
    pub token_b_mint: Pubkey,
    pub token_a_reserve: Pubkey,
    pub token_b_reserve: Pubkey,
    pub lp_mint: Pubkey,
    pub lp_supply: u64,
    pub fee_bps: u64,
    pub created_at: u64,
    pub admin: Pubkey,
    pub is_active: bool,
    pub total_volume_a: u64,
    pub total_volume_b: u64,
    pub bump: u8,
}
// Space: 8 + 32*5 + 8*6 + 1 + 1 = 178

// ── Program entrypoints ──

#[program]
pub mod amm {
    use super::*;

    pub fn initialize_config(ctx: Context<InitializeConfig>) -> Result<()> {
        let config = &mut ctx.accounts.config;
        let admin = &ctx.accounts.admin;

        config.admin = admin.key();
        config.total_pools = 0;
        config.fee_bps = 30;

        Ok(())
    }

    pub fn create_pool(ctx: Context<CreatePool>, fee_bps: u64) -> Result<()> {
        let config = &mut ctx.accounts.config;
        let pool = &mut ctx.accounts.pool;

        require!(ctx.accounts.creator.key() == config.admin, AmmError::Unauthorized);
        require!(fee_bps <= 1000, AmmError::InvalidFeeBps);

        pool.token_a_mint = ctx.accounts.token_a_mint.key();
        pool.token_b_mint = ctx.accounts.token_b_mint.key();
        pool.token_a_reserve = ctx.accounts.token_a_reserve.key();
        pool.token_b_reserve = ctx.accounts.token_b_reserve.key();
        pool.lp_mint = ctx.accounts.lp_mint.key();
        pool.lp_supply = 0;
        pool.fee_bps = fee_bps;
        pool.created_at = ctx.accounts.clock.unix_timestamp as u64;
        pool.admin = ctx.accounts.creator.key();
        pool.is_active = true;
        pool.total_volume_a = 0;
        pool.total_volume_b = 0;

        config.total_pools += 1;

        emit!(PoolCreated {
            pool: pool.key(),
            token_a: ctx.accounts.token_a_mint.key(),
            token_b: ctx.accounts.token_b_mint.key(),
        });

        Ok(())
    }

    pub fn add_liquidity(
        ctx: Context<AddLiquidity>,
        amount_a: u64,
        amount_b: u64,
        min_lp_tokens: u64,
    ) -> Result<()> {
        let pool = &mut ctx.accounts.pool;

        require!(pool.is_active, AmmError::PoolDoesNotExist);
        require!(amount_a > 0, AmmError::InvalidAmount);
        require!(amount_b > 0, AmmError::InvalidAmount);

        let mut lp_tokens: u64 = 0;

        if pool.lp_supply == 0 {
            lp_tokens = (amount_a * amount_b) / 1_000_000;
            require!(lp_tokens > 0, AmmError::InvalidAmount);
        } else {
            let lp_from_a = (amount_a * pool.lp_supply) / ctx.accounts.token_a_reserve.amount;
            let lp_from_b = (amount_b * pool.lp_supply) / ctx.accounts.token_b_reserve.amount;
            lp_tokens = if lp_from_a < lp_from_b { lp_from_a } else { lp_from_b };
        }

        require!(lp_tokens >= min_lp_tokens, AmmError::SlippageExceeded);

        // CPI: transfer token A from depositor to pool reserve
        token::transfer(
            CpiContext::new(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.depositor_token_a.to_account_info(),
                    to: ctx.accounts.token_a_reserve.to_account_info(),
                    authority: ctx.accounts.depositor.to_account_info(),
                },
            ),
            amount_a,
        )?;

        // CPI: transfer token B from depositor to pool reserve
        token::transfer(
            CpiContext::new(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.depositor_token_b.to_account_info(),
                    to: ctx.accounts.token_b_reserve.to_account_info(),
                    authority: ctx.accounts.depositor.to_account_info(),
                },
            ),
            amount_b,
        )?;

        // CPI: mint LP tokens to depositor (PDA-signed)
        let seeds = &[
            b"pool",
            pool.token_a_mint.as_ref(),
            pool.token_b_mint.as_ref(),
            &[pool.bump],
        ];
        token::mint_to(
            CpiContext::new_with_signer(
                ctx.accounts.token_program.to_account_info(),
                MintTo {
                    mint: ctx.accounts.lp_mint.to_account_info(),
                    to: ctx.accounts.depositor_lp.to_account_info(),
                    authority: pool.to_account_info(),
                },
                &[seeds],
            ),
            lp_tokens,
        )?;

        pool.lp_supply += lp_tokens;
        pool.total_volume_a += amount_a;
        pool.total_volume_b += amount_b;

        emit!(LiquidityAdded {
            pool: pool.key(),
            amount_a,
            amount_b,
            lp_tokens,
        });

        Ok(())
    }

    pub fn remove_liquidity(
        ctx: Context<RemoveLiquidity>,
        lp_tokens: u64,
        min_amount_a: u64,
        min_amount_b: u64,
    ) -> Result<()> {
        let pool = &mut ctx.accounts.pool;

        require!(pool.is_active, AmmError::PoolDoesNotExist);
        require!(lp_tokens > 0, AmmError::InvalidAmount);
        require!(pool.lp_supply > 0, AmmError::InsufficientLiquidity);

        let amount_a = (lp_tokens * ctx.accounts.token_a_reserve.amount) / pool.lp_supply;
        let amount_b = (lp_tokens * ctx.accounts.token_b_reserve.amount) / pool.lp_supply;

        require!(amount_a >= min_amount_a, AmmError::SlippageExceeded);
        require!(amount_b >= min_amount_b, AmmError::SlippageExceeded);

        // CPI: burn LP tokens
        token::burn(
            CpiContext::new(
                ctx.accounts.token_program.to_account_info(),
                Burn {
                    mint: ctx.accounts.lp_mint.to_account_info(),
                    from: ctx.accounts.withdrawer_lp.to_account_info(),
                    authority: ctx.accounts.withdrawer.to_account_info(),
                },
            ),
            lp_tokens,
        )?;

        // CPI: transfer token A from pool to withdrawer (PDA-signed)
        let seeds = &[
            b"pool",
            pool.token_a_mint.as_ref(),
            pool.token_b_mint.as_ref(),
            &[pool.bump],
        ];
        token::transfer(
            CpiContext::new_with_signer(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.token_a_reserve.to_account_info(),
                    to: ctx.accounts.withdrawer_token_a.to_account_info(),
                    authority: pool.to_account_info(),
                },
                &[seeds],
            ),
            amount_a,
        )?;

        // CPI: transfer token B from pool to withdrawer (PDA-signed)
        token::transfer(
            CpiContext::new_with_signer(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.token_b_reserve.to_account_info(),
                    to: ctx.accounts.withdrawer_token_b.to_account_info(),
                    authority: pool.to_account_info(),
                },
                &[seeds],
            ),
            amount_b,
        )?;

        pool.lp_supply -= lp_tokens;

        emit!(LiquidityRemoved {
            pool: pool.key(),
            amount_a,
            amount_b,
            lp_tokens,
        });

        Ok(())
    }

    pub fn swap_a_for_b(
        ctx: Context<SwapAForB>,
        amount_in: u64,
        min_out: u64,
    ) -> Result<()> {
        let pool = &mut ctx.accounts.pool;

        require!(pool.is_active, AmmError::PoolDoesNotExist);
        require!(amount_in > 0, AmmError::InvalidAmount);

        let reserve_in = ctx.accounts.token_a_reserve.amount;
        let reserve_out = ctx.accounts.token_b_reserve.amount;
        let fee = (amount_in * pool.fee_bps) / 10000;
        let net_in = amount_in - fee;
        let amount_out = (net_in * reserve_out) / (reserve_in + net_in);

        require!(amount_out >= min_out, AmmError::SlippageExceeded);

        // CPI: transfer token A from trader to pool (user-signed)
        token::transfer(
            CpiContext::new(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.trader_token_a.to_account_info(),
                    to: ctx.accounts.token_a_reserve.to_account_info(),
                    authority: ctx.accounts.trader.to_account_info(),
                },
            ),
            amount_in,
        )?;

        // CPI: transfer token B from pool to trader (PDA-signed)
        let seeds = &[
            b"pool",
            pool.token_a_mint.as_ref(),
            pool.token_b_mint.as_ref(),
            &[pool.bump],
        ];
        token::transfer(
            CpiContext::new_with_signer(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.token_b_reserve.to_account_info(),
                    to: ctx.accounts.trader_token_b.to_account_info(),
                    authority: pool.to_account_info(),
                },
                &[seeds],
            ),
            amount_out,
        )?;

        pool.total_volume_a += amount_in;
        pool.total_volume_b += amount_out;

        emit!(SwapExecuted {
            pool: pool.key(),
            amount_in,
            amount_out,
            fee,
            direction: 0,
        });

        Ok(())
    }

    pub fn swap_b_for_a(
        ctx: Context<SwapBForA>,
        amount_in: u64,
        min_out: u64,
    ) -> Result<()> {
        let pool = &mut ctx.accounts.pool;

        require!(pool.is_active, AmmError::PoolDoesNotExist);
        require!(amount_in > 0, AmmError::InvalidAmount);

        let reserve_in = ctx.accounts.token_b_reserve.amount;
        let reserve_out = ctx.accounts.token_a_reserve.amount;
        let fee = (amount_in * pool.fee_bps) / 10000;
        let net_in = amount_in - fee;
        let amount_out = (net_in * reserve_out) / (reserve_in + net_in);

        require!(amount_out >= min_out, AmmError::SlippageExceeded);

        // CPI: transfer token B from trader to pool (user-signed)
        token::transfer(
            CpiContext::new(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.trader_token_b.to_account_info(),
                    to: ctx.accounts.token_b_reserve.to_account_info(),
                    authority: ctx.accounts.trader.to_account_info(),
                },
            ),
            amount_in,
        )?;

        // CPI: transfer token A from pool to trader (PDA-signed)
        let seeds = &[
            b"pool",
            pool.token_a_mint.as_ref(),
            pool.token_b_mint.as_ref(),
            &[pool.bump],
        ];
        token::transfer(
            CpiContext::new_with_signer(
                ctx.accounts.token_program.to_account_info(),
                Transfer {
                    from: ctx.accounts.token_a_reserve.to_account_info(),
                    to: ctx.accounts.trader_token_a.to_account_info(),
                    authority: pool.to_account_info(),
                },
                &[seeds],
            ),
            amount_out,
        )?;

        pool.total_volume_a += amount_out;
        pool.total_volume_b += amount_in;

        emit!(SwapExecuted {
            pool: pool.key(),
            amount_in,
            amount_out,
            fee,
            direction: 1,
        });

        Ok(())
    }

    pub fn update_fee(ctx: Context<UpdateFee>, new_fee_bps: u64) -> Result<()> {
        let pool = &mut ctx.accounts.pool;

        require!(ctx.accounts.admin.key() == pool.admin, AmmError::Unauthorized);
        require!(new_fee_bps <= 1000, AmmError::InvalidFeeBps);

        pool.fee_bps = new_fee_bps;

        emit!(FeeUpdated {
            pool: pool.key(),
            new_fee_bps,
        });
        msg!("Fee updated to {}bps", new_fee_bps);

        Ok(())
    }
}

