// Error definition returns a registry where keys are the error names
function defineErrors<const T extends Record<string, string>>(errors: T): T {
  return errors
}

type ErrorName<T extends Record<string, string>> = keyof T & string

// The require function signature:
// require(condition) — no error specified
// require(condition, errorName) — must be a key from the error registry
// 
// The trick: require() needs to know about the error registry.
// The error registry is defined at the MODULE level.
// How does require() know about it?
//
// Option A: require is a method that takes the error registry as context
// Option B: require is created by a factory that captures the registry type
// Option C: The ix() function creates a scoped require that knows the errors
// Option D: The program() function returns a typed require

// Option C is the cleanest — ix() knows the error type from the program

// Let me prototype Option C:

interface ProgramDef<
  TName extends string,
  TErrors extends Record<string, string>,
  TAccounts extends Record<string, any>,
> {
  name: TName
  errors: TErrors
  accounts: TAccounts
}

function program<
  const TName extends string,
  const TErrors extends Record<string, string>,
  const TInstructions extends Record<string, any>,
>(
  name: TName,
  errors: TErrors,
  instructions: TInstructions & {
    [K in keyof TInstructions]: TInstructions[K] extends { run: (ctx: any, args: any, api: infer Api) => any } 
      ? TInstructions[K] 
      : never
  }
): ProgramDef<TName, TErrors, {}> {
  return { name, errors, accounts: {} } as any
}

// The ix() function creates a typed instruction that has access to 
// a scoped require() that knows the error names
function ix<
  const TErrors extends Record<string, string>,
  const TConfig extends {
    accounts: any,
    args?: any,
    run: (ctx: any, args: any, api: { 
      require: (condition: boolean, error?: ErrorName<TErrors>) => void 
    }) => void,
  }
>(errors: TErrors, config: TConfig): TConfig {
  return config
}

