// Hmm, this approach requires passing errors to every ix() call.
// That's repetitive. Let me think of something better.

// ═══ BETTER APPROACH: Curried factory ═══

// program() returns a namespace with a typed ix() inside it
// This is the Elysia pattern — methods on the class carry type info

interface ProgramBuilder<TName extends string, TErrors extends Record<string, string>> {
  ix: <const TConfig extends {
    accounts: any,
    args?: any,
    run: (...args: any[]) => void,
  }>(config: TConfig) => TConfig & { __errors: TErrors }
  // The run function inside TConfig needs access to a scoped require...
  // But we can't change the run() signature from inside a type alias.
}

