// TYPE-SAFE ERRORS v2: The run() receives a scoped API object
//
// Key insight from Elysia: The handler function receives typed context.
// Our run() function receives typed context too.
// The FIRST parameter is the accounts (already typed).
// We can ADD the error-typed require() to that context.
//
// Instead of:
//   run: ({ pool, authority }, { amount }) => { require(...) }
//
// We do:
//   run: ({ pool, authority }, { amount }, { require }) => { require(...) }
//
// But 3 params is awkward. Better: merge require into the first param.
//
// Actually, the SIMPLEST approach: make require() a top-level function
// that's GENERIC over the program's error type. The program() call
// returns a NAMED require that's already typed.
//
// Like Elysia's error() method — it knows the error types because
// they're class generic parameters that flow through every method.
//
// For a FUNCTION-based API (not class-based), the equivalent is:
// program() returns an object with a typed .require() method.
// ============================================================

type SolTypeMap = { u64: bigint; u8: number; bool: boolean; pubkey: string }
interface SolField<T extends keyof SolTypeMap = keyof SolTypeMap> { readonly __sol: T }
const u64: SolField<'u64'> = { __sol: 'u64' }
const pubkey: SolField<'pubkey'> = { __sol: 'pubkey' }
const bool: SolField<'bool'> = { __sol: 'bool' }
type PubkeyFields<T extends Record<string, SolField>> = { [K in keyof T]: T[K] extends SolField<'pubkey'> ? K : never }[keyof T]
interface SolAccount<T extends Record<string, SolField>> { readonly __fields: T }
declare function account<const T extends Record<string, SolField>>(fields: T): SolAccount<T>

// ── Error Registry ──

interface ErrorRegistry<T extends Record<string, string>> {
  __errors: T
}

function defineErrors<const T extends Record<string, string>>(errors: T): ErrorRegistry<T> {
  return { __errors: errors } as any
}

// ── The program() function returns a NAMESPACE with typed helpers ──

interface ProgramNamespace<
  TName extends string,
  TId extends string,
  TErrors extends Record<string, string>,
> {
  name: TName
  id: TId
  errors: TErrors

  // Typed require — only accepts keys from TErrors
  require: (condition: boolean, error: keyof TErrors & string) => void

  // Typed ix — the run() function gets { require } as 3rd param
  ix: <const TConfig extends {
    accounts: Record<string, any>,
    args?: Record<string, SolField>,
    run: (
      accounts: any,  // typed from accounts
      args: any,       // typed from args
      api: {
        require: (condition: boolean, error?: keyof TErrors & string) => void
        log: (...args: any[]) => void
        emit: (...args: any[]) => void
      }
    ) => void,
  }>(config: TConfig) => TConfig
}

function program<
  const TName extends string,
  const TId extends string,
  const TErrors extends Record<string, string>,
>(
  name: TName,
  id: TId,
  errors: ErrorRegistry<TErrors>,
): ProgramNamespace<TName, TId, TErrors> {
  return {
    name,
    id,
    errors: errors.__errors,
    require: () => {},
    ix: (config: any) => config,
  } as any
}

