//   - amm.ix({ run: (ctx, args, { require }) => ... }) — type-safe
//
// But developers want to write require() without amm. prefix.
//
// The trick: destructure it!
//
//   const { require, ix } = program('amm', '...', errors)
//   
//   ix({ run: ({ pool }, { amount }) => {
//     require(amount > 0n, 'InvalidAmount')  // ✅ type-safe!
//   }})
//
