// ============================================================
// AMM (Automated Market Maker) — Complete Program
//
// Written in @solana-kit/program syntax
// This file defines the on-chain program AND serves as the
// typed client SDK — zero additional code needed.
//
// What this exercises:
// - Multiple accounts with PDA seeds
// - Complex arithmetic (constant product formula, fees)
// - Multiple CPI calls per instruction
// - User-signed and PDA-signed token transfers
// - Token minting and burning (LP tokens)
// - Events and logging
// - Sysvars (timestamp)
// - Access control with type-safe custom errors
// - Type-safe token account field references
// - 7 instructions that compose together
//
// Type safety:
// - amm.require(cond, 'ErrorName') — autocomplete, compile-time checked
// - p.tokenAccount(Pool, 'fieldName') — only pubkey fields accepted
// ============================================================

import {
  program, account, ix, defineErrors,
  u64, u8, bool, pubkey,
  p, token, sol, emit, log,
} from '@solana-kit/program'


// ══════════════════════════════════════════
// ACCOUNTS — Like Zod schemas
// ══════════════════════════════════════════

const Config = account({
  admin: pubkey,
  totalPools: u64,
  feeBps: u64,
  bump: u8,
}).seeds('config')

const Pool = account({
  tokenAMint: pubkey,
  tokenBMint: pubkey,
  tokenAReserve: pubkey,
  tokenBReserve: pubkey,
  lpMint: pubkey,
  lpSupply: u64,
  feeBps: u64,
  createdAt: u64,
  admin: pubkey,
  isActive: bool,
  totalVolumeA: u64,
  totalVolumeB: u64,
  bump: u8,
}).seeds('pool', '{tokenAMint}', '{tokenBMint}')


// ══════════════════════════════════════════
// ERRORS — defineErrors() creates a typed registry
// Used by amm.require() for autocomplete + validation
// ══════════════════════════════════════════

const errors = defineErrors({
  Unauthorized: 'Caller is not authorized',
  PoolDoesNotExist: 'Pool does not exist or is inactive',
  InsufficientLiquidity: 'Not enough liquidity in the pool',
  SlippageExceeded: 'Output amount below minimum (slippage)',
  InvalidAmount: 'Amount must be greater than zero',
  InvalidFeeBps: 'Fee must be between 0 and 1000 basis points',
})


// ══════════════════════════════════════════
// PROGRAM — Flat instruction map
//
// amm.require() is type-safe: only accepts keys from errors above
// amm.ix() creates typed instructions
// ══════════════════════════════════════════

export const amm = program('amm', 'AMMxPooL11111111111111111111111111111111111', errors, {

  // ── 1. Initialize the global config ──
  initializeConfig: ix({
    accounts: {
      config: p.init(Config),
      admin: p.signer(),
    },
    run: ({ config, admin }) => {
      config.admin = admin
      config.totalPools = 0n
      config.feeBps = 30n
    },
  }),

  // ── 2. Create a new trading pool ──
  createPool: ix({
    accounts: {
      config: Config,
      pool: p.init(Pool),
      tokenAMint: p.mint(),
      tokenBMint: p.mint(),
      creator: p.signer(),
    },
    args: { feeBps: u64 },
    run: ({ config, pool, tokenAMint, tokenBMint, creator }, { feeBps }) => {
      amm.require(creator === config.admin, 'Unauthorized')
      amm.require(feeBps <= 1000n, 'InvalidFeeBps')

      pool.tokenAMint = tokenAMint
      pool.tokenBMint = tokenBMint
      pool.lpSupply = 0n
      pool.feeBps = feeBps
      pool.createdAt = sol.timestamp()
      pool.admin = creator
      pool.isActive = true
      pool.totalVolumeA = 0n
      pool.totalVolumeB = 0n

      config.totalPools += 1n

      emit('PoolCreated', { pool, tokenA: tokenAMint, tokenB: tokenBMint })
    },
  }),

  // ── 3. Add liquidity to a pool ──
  addLiquidity: ix({
    accounts: {
      pool: p.mut(Pool),
      // p.tokenAccount(Pool, 'fieldName') — type-safe: only pubkey fields accepted
      tokenAReserve: p.tokenAccount(Pool, 'tokenAMint').mut(),
      tokenBReserve: p.tokenAccount(Pool, 'tokenBMint').mut(),
      lpMint: p.mint().mut(),
      depositorTokenA: p.tokenAccount(Pool, 'tokenAMint').mut(),
      depositorTokenB: p.tokenAccount(Pool, 'tokenBMint').mut(),
      depositorLp: p.tokenAccount(Pool, 'lpMint').mut(),
      depositor: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { amountA: u64, amountB: u64, minLpTokens: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, lpMint, depositorTokenA, depositorTokenB, depositorLp, depositor }, { amountA, amountB, minLpTokens }) => {
      amm.require(pool.isActive, 'PoolDoesNotExist')
      amm.require(amountA > 0n, 'InvalidAmount')
      amm.require(amountB > 0n, 'InvalidAmount')

      let lpTokens = 0n

      if (pool.lpSupply === 0n) {
        // First deposit: LP tokens = geometric mean
        lpTokens = (amountA * amountB) / 1000000n
        amm.require(lpTokens > 0n, 'InvalidAmount')
      } else {
        // Subsequent deposits: proportional to existing liquidity
        const lpFromA = (amountA * pool.lpSupply) / tokenAReserve.amount
        const lpFromB = (amountB * pool.lpSupply) / tokenBReserve.amount
        lpTokens = lpFromA < lpFromB ? lpFromA : lpFromB
      }

      amm.require(lpTokens >= minLpTokens, 'SlippageExceeded')

      // Transfer both tokens from depositor to pool reserves
      token.transfer({ from: depositorTokenA, to: tokenAReserve, authority: depositor, amount: amountA })
      token.transfer({ from: depositorTokenB, to: tokenBReserve, authority: depositor, amount: amountB })

      // Mint LP tokens to depositor (PDA-signed — pool is the authority)
      token.mintTo({ mint: lpMint, to: depositorLp, authority: pool, amount: lpTokens })

      pool.lpSupply += lpTokens
      pool.totalVolumeA += amountA
      pool.totalVolumeB += amountB

      emit('LiquidityAdded', { pool, amountA, amountB, lpTokens })
    },
  }),

  // ── 4. Remove liquidity from a pool ──
  removeLiquidity: ix({
    accounts: {
      pool: p.mut(Pool),
      tokenAReserve: p.tokenAccount(Pool, 'tokenAMint').mut(),
      tokenBReserve: p.tokenAccount(Pool, 'tokenBMint').mut(),
      lpMint: p.mint().mut(),
      withdrawerTokenA: p.tokenAccount(Pool, 'tokenAMint').mut(),
      withdrawerTokenB: p.tokenAccount(Pool, 'tokenBMint').mut(),
      withdrawerLp: p.tokenAccount(Pool, 'lpMint').mut(),
      withdrawer: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { lpTokens: u64, minAmountA: u64, minAmountB: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, lpMint, withdrawerTokenA, withdrawerTokenB, withdrawerLp, withdrawer }, { lpTokens, minAmountA, minAmountB }) => {
      amm.require(pool.isActive, 'PoolDoesNotExist')
      amm.require(lpTokens > 0n, 'InvalidAmount')
      amm.require(pool.lpSupply > 0n, 'InsufficientLiquidity')

      // Calculate proportional withdrawal
      const amountA = (lpTokens * tokenAReserve.amount) / pool.lpSupply
      const amountB = (lpTokens * tokenBReserve.amount) / pool.lpSupply

      amm.require(amountA >= minAmountA, 'SlippageExceeded')
      amm.require(amountB >= minAmountB, 'SlippageExceeded')

      // Burn the LP tokens
      token.burn({ from: withdrawerLp, mint: lpMint, authority: withdrawer, amount: lpTokens })

      // Transfer proportional amounts back (PDA-signed)
      token.transfer({ from: tokenAReserve, to: withdrawerTokenA, authority: pool, amount: amountA })
      token.transfer({ from: tokenBReserve, to: withdrawerTokenB, authority: pool, amount: amountB })

      pool.lpSupply -= lpTokens

      emit('LiquidityRemoved', { pool, amountA, amountB, lpTokens })
    },
  }),

  // ── 5. Swap token A → token B ──
  swapAForB: ix({
    accounts: {
      pool: p.mut(Pool),
      tokenAReserve: p.tokenAccount(Pool, 'tokenAMint').mut(),
      tokenBReserve: p.tokenAccount(Pool, 'tokenBMint').mut(),
      traderTokenA: p.tokenAccount(Pool, 'tokenAMint').mut(),
      traderTokenB: p.tokenAccount(Pool, 'tokenBMint').mut(),
      trader: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { amountIn: u64, minOut: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, traderTokenA, traderTokenB, trader }, { amountIn, minOut }) => {
      amm.require(pool.isActive, 'PoolDoesNotExist')
      amm.require(amountIn > 0n, 'InvalidAmount')

      // Constant product formula: x * y = k
      const fee = (amountIn * pool.feeBps) / 10000n
      const netIn = amountIn - fee
      const amountOut = (netIn * tokenBReserve.amount) / (tokenAReserve.amount + netIn)

      amm.require(amountOut >= minOut, 'SlippageExceeded')

      // Transfer A from trader to pool (user-signed)
      token.transfer({ from: traderTokenA, to: tokenAReserve, authority: trader, amount: amountIn })

      // Transfer B from pool to trader (PDA-signed)
      token.transfer({ from: tokenBReserve, to: traderTokenB, authority: pool, amount: amountOut })

      pool.totalVolumeA += amountIn
      pool.totalVolumeB += amountOut

      emit('SwapExecuted', { pool, amountIn, amountOut, fee, direction: 0 })
    },
  }),

  // ── 6. Swap token B → token A ──
  swapBForA: ix({
    accounts: {
      pool: p.mut(Pool),
      tokenAReserve: p.tokenAccount(Pool, 'tokenAMint').mut(),
      tokenBReserve: p.tokenAccount(Pool, 'tokenBMint').mut(),
      traderTokenA: p.tokenAccount(Pool, 'tokenAMint').mut(),
      traderTokenB: p.tokenAccount(Pool, 'tokenBMint').mut(),
      trader: p.signer(),
      tokenProgram: p.tokenProgram(),
    },
    args: { amountIn: u64, minOut: u64 },
    run: ({ pool, tokenAReserve, tokenBReserve, traderTokenA, traderTokenB, trader }, { amountIn, minOut }) => {
      amm.require(pool.isActive, 'PoolDoesNotExist')
      amm.require(amountIn > 0n, 'InvalidAmount')

      // Constant product formula (reversed reserves)
      const fee = (amountIn * pool.feeBps) / 10000n
      const netIn = amountIn - fee
      const amountOut = (netIn * tokenAReserve.amount) / (tokenBReserve.amount + netIn)

      amm.require(amountOut >= minOut, 'SlippageExceeded')

      // Transfer B from trader to pool (user-signed)
      token.transfer({ from: traderTokenB, to: tokenBReserve, authority: trader, amount: amountIn })

      // Transfer A from pool to trader (PDA-signed)
      token.transfer({ from: tokenAReserve, to: traderTokenA, authority: pool, amount: amountOut })

      pool.totalVolumeA += amountOut
      pool.totalVolumeB += amountIn

      emit('SwapExecuted', { pool, amountIn, amountOut, fee, direction: 1 })
    },
  }),

  // ── 7. Update pool fee (admin only) ──
  updateFee: ix({
    accounts: {
      pool: p.mut(Pool),
      admin: p.signer(),
    },
    args: { newFeeBps: u64 },
    run: ({ pool, admin }, { newFeeBps }) => {
      amm.require(admin === pool.admin, 'Unauthorized')
      amm.require(newFeeBps <= 1000n, 'InvalidFeeBps')

      pool.feeBps = newFeeBps

      emit('FeeUpdated', { pool, newFeeBps })
      log('Fee updated to {}bps', newFeeBps)
    },
  }),
})

// ============================================================
// Counter Program — The "Hello World" of Solana
//
// This is what a developer sees FIRST when they try our library.
// It should be dead simple, instantly understandable.
//
// Compare to Anchor (Rust):
//   - Anchor: ~80 lines across 3 files (lib.rs, mod.rs, Cargo.toml)
//   - Ours:   ~40 lines in ONE file
//
// And the same file is the typed client SDK. Zero extra code.
//
// Type safety:
// - counter.require(cond, 'ErrorName') — autocomplete, compile-time checked
// ============================================================

import {
  program, account, ix, defineErrors,
  u64, bool, pubkey,
  p,
} from '@solana-kit/program'

// Define the counter account — like a Zod schema
const Counter = account({
  count: u64,
  authority: pubkey,
  isActive: bool,
}).seeds('counter', '{authority}')

// Define errors — type-safe via counter.require()
const errors = defineErrors({
  Unauthorized: 'Only the creator can perform this action',
  NotActive: 'Counter is not active',
  BelowZero: 'Counter would go below zero',
})

// Define the program — flat instruction map
export const counter = program('counter', 'CouNTeR11111111111111111111111111111111111', errors, {

  // Create a new counter
  initialize: ix({
    accounts: {
      counter: p.init(Counter),
      authority: p.signer(),
    },
    args: { initialValue: u64 },
    run: ({ counter, authority }, { initialValue }) => {
      counter.count = initialValue
      counter.authority = authority
      counter.isActive = true
    },
  }),

  // Increment the counter
  increment: ix({
    accounts: {
      counter: p.mut(Counter),
      authority: p.signer(),
    },
    args: { amount: u64 },
    run: ({ counter, authority }, { amount }) => {
      counter.require(authority === counter.authority, 'Unauthorized')
      counter.require(counter.isActive, 'NotActive')
      counter.count += amount
    },
  }),

  // Decrement the counter
  decrement: ix({
    accounts: {
      counter: p.mut(Counter),
      authority: p.signer(),
    },
    args: { amount: u64 },
    run: ({ counter, authority }, { amount }) => {
      counter.require(authority === counter.authority, 'Unauthorized')
      counter.require(counter.isActive, 'NotActive')
      counter.require(counter.count >= amount, 'BelowZero')
      counter.count -= amount
    },
  }),

  // Toggle the active status
  toggle: ix({
    accounts: {
      counter: p.mut(Counter),
      authority: p.signer(),
    },
    run: ({ counter, authority }) => {
      counter.require(authority === counter.authority, 'Unauthorized')
      counter.isActive = !counter.isActive
    },
  }),

  // Close the counter and recover rent
  close: ix({
    accounts: {
      counter: p.close(Counter, 'authority'),
      authority: p.signer(),
    },
    run: ({}) => {
      // Account is closed automatically by p.close()
    },
  }),
})


// ══════════════════════════════════════════
// Client usage (same file, zero extra code)
// ══════════════════════════════════════════

import { createClient } from '@solana-kit/sdk'

const client = createClient({
  cluster: 'devnet',
  payer: './keypair.json',
  programs: { counter },
})

const payer = client.payer

// Derive the counter PDA from seed definition
const counterAddr = counter.accounts.Counter.derive({ authority: payer })

// Create a counter starting at 42
await client.counter.initialize({
  counter: counterAddr,
  authority: payer,
  initialValue: 42n,
})

// Increment by 10
await client.counter.increment({
  counter: counterAddr,
  authority: payer,
  amount: 10n,
})

// Fetch the account (fully typed)
const data = await counter.accounts.Counter.fetch(counterAddr)
console.log(data.count)     // 52n
console.log(data.isActive)  // true

// Decrement by 2
await client.counter.decrement({
  counter: counterAddr,
  authority: payer,
  amount: 2n,
})

// Close it
await client.counter.close({
  counter: counterAddr,
  authority: payer,
})

