// ============================================================
// Counter Program — The "Hello World" of Solana
//
// This is what a developer sees FIRST when they try our library.
// It should be dead simple, instantly understandable.
//
// Compare to Anchor (Rust):
//   - Anchor: ~80 lines across 3 files (lib.rs, mod.rs, Cargo.toml)
//   - Ours:   ~40 lines in ONE file
//
// And the same file is the typed client SDK. Zero extra code.
//
// Type safety:
// - counter.require(cond, 'ErrorName') — autocomplete, compile-time checked
// ============================================================

import {
  program, account, ix, defineErrors,
  u64, bool, pubkey,
  p,
} from '@solana-kit/program'

// Define the counter account — like a Zod schema
const Counter = account({
  count: u64,
  authority: pubkey,
  isActive: bool,
}).seeds('counter', '{authority}')

// Define errors — type-safe via counter.require()
const errors = defineErrors({
  Unauthorized: 'Only the creator can perform this action',
  NotActive: 'Counter is not active',
  BelowZero: 'Counter would go below zero',
})

// Define the program — flat instruction map
export const counter = program('counter', 'CouNTeR11111111111111111111111111111111111', errors, {

  // Create a new counter
  initialize: ix({
    accounts: {
      counter: p.init(Counter),
      authority: p.signer(),
    },
    args: { initialValue: u64 },
    run: ({ counter, authority }, { initialValue }) => {
      counter.count = initialValue
      counter.authority = authority
      counter.isActive = true
    },
  }),

  // Increment the counter
  increment: ix({
    accounts: {
      counter: p.mut(Counter),
      authority: p.signer(),
    },
    args: { amount: u64 },
    run: ({ counter, authority }, { amount }) => {
      counter.require(authority === counter.authority, 'Unauthorized')
      counter.require(counter.isActive, 'NotActive')
      counter.count += amount
    },
  }),

  // Decrement the counter
  decrement: ix({
    accounts: {
      counter: p.mut(Counter),
      authority: p.signer(),
    },
    args: { amount: u64 },
    run: ({ counter, authority }, { amount }) => {
      counter.require(authority === counter.authority, 'Unauthorized')
      counter.require(counter.isActive, 'NotActive')
      counter.require(counter.count >= amount, 'BelowZero')
      counter.count -= amount
    },
  }),

  // Toggle the active status
  toggle: ix({
    accounts: {
      counter: p.mut(Counter),
      authority: p.signer(),
    },
    run: ({ counter, authority }) => {
      counter.require(authority === counter.authority, 'Unauthorized')
      counter.isActive = !counter.isActive
    },
  }),

  // Close the counter and recover rent
  close: ix({
    accounts: {
      counter: p.close(Counter, 'authority'),
      authority: p.signer(),
    },
    run: ({}) => {
      // Account is closed automatically by p.close()
    },
  }),
})


