// ============================================================
// TYPE INFERENCE POC: require as 3rd parameter of run:
//
// Question: Can TypeScript infer the error registry type
// from program() → ix() → run: callback's 3rd parameter?
//
// Pattern: ElysiaJS-style — handler receives typed context.
// program() carries TErrors as const generic.
// ix()'s run callback receives require typed by TErrors.
// TypeScript infers ALL of this from the call site.
//
// This is the SAME pattern as:
//   ElysiaJS: .error({...}).get('/path', (ctx) => ctx.error('Name'))
//   Drizzle:  pgTable('name', {...}). then db.insert(table).values({...})
//   Better Auth: createAuth({ plugins }). then auth.api.pluginMethod()
// ============================================================

// ══════════════════════════════════════════
// TYPE SYSTEM (internal to @solana-kit/program)
// ══════════════════════════════════════════

type SolTypeMap = {
  u64: bigint
  u8: number
  u32: number
  bool: boolean
  pubkey: string
}

interface SolField<T extends keyof SolTypeMap = keyof SolTypeMap> {
  readonly __sol: T
}

declare const u64: SolField<'u64'>
declare const u8: SolField<'u8'>
declare const bool: SolField<'bool'>
declare const pubkey: SolField<'pubkey'>

type InferFields<T extends Record<string, SolField>> = {
  [K in keyof T]: SolTypeMap[T[K]['__sol']]
}

interface SolAccount<T extends Record<string, SolField>> {
  readonly __fields: T
}

declare function account<const T extends Record<string, SolField>>(fields: T): SolAccount<T>

interface ErrorRegistry<T extends Record<string, string>> {
  readonly __errors: T
}

declare function defineErrors<const T extends Record<string, string>>(errors: T): ErrorRegistry<T>

// Type-safe require function — error name constrained by TErrors
type RequireFn<TErrors extends Record<string, string>> = {
  (condition: boolean): void
  (condition: boolean, error: keyof TErrors & string): void
}

// p.* constraint builders
declare const p: {
  init<T extends Record<string, SolField>>(acct: SolAccount<T>): void
  mut<T extends Record<string, SolField>>(acct: SolAccount<T>): void
  signer(): void
  close<T extends Record<string, SolField>>(acct: SolAccount<T>, refundTo: string): void
}

// ix() — the instruction builder.
// Key: TErrors flows from program() → ix() → run:'s 3rd parameter.
// TypeScript infers this through const generic parameters.
interface IxConfig<
  TAccounts extends Record<string, any>,
  TArgs extends Record<string, SolField>,
  TErrors extends Record<string, string>,
> {
  accounts: TAccounts
  args?: TArgs
  run: (
    accounts: { [K in keyof TAccounts]: any },
    args: { [K in keyof TArgs]: SolTypeMap[TArgs[K]['__sol']] },
    require: RequireFn<TErrors>,
  ) => void
}

// This overload allows ix() to be called with or without args
declare function ix<
  const TErrors extends Record<string, string>,
  const TAccounts extends Record<string, any>,
  const TArgs extends Record<string, SolField>,
>(config: IxConfig<TAccounts, TArgs, TErrors>): IxConfig<TAccounts, TArgs, TErrors>

// program() — carries TErrors through to instruction run: callbacks.
// The const generic ensures literal error names are preserved.
// The instructions object's run: callbacks receive typed require.
interface ProgramApi<
  const TName extends string,
  const TId extends string,
  const TErrors extends Record<string, string>,
> {
  readonly name: TName
  readonly id: TId
  readonly errors: TErrors
}

// CRITICAL: This is where the type magic happens.
// program() takes errors AND instructions together.
// The instruction configs reference TErrors for their run: callbacks.
// TypeScript infers TErrors from the errors parameter,
// then validates that all run: callbacks' require functions match.
declare function program<
  const TName extends string,
  const TId extends string,
  const TErrors extends Record<string, string>,
  const TInstructions extends Record<string, IxConfig<any, any, TErrors>>,
>(
  name: TName,
  id: TId,
  errors: ErrorRegistry<TErrors>,
  instructions: TInstructions,
): ProgramApi<TName, TId, TErrors> & {
  [K in keyof TInstructions]: TInstructions[K]
}


// ╔═════════════════════════════════════════════════════╗
// ║  DEVELOPER CODE — THE DX WE'RE SHIPPING            ║
// ╚═════════════════════════════════════════════════════╝


// ── Counter Program (the naming collision case) ──

const Counter = account({
  count: u64,
  authority: pubkey,
  isActive: bool,
})

const counterErrors = defineErrors({
  Unauthorized: 'Not the authority',
  NotActive: 'Counter not active',
  BelowZero: 'Count would go below zero',
})

// ✅ 'counter' can be both the program name AND the account name.
// No collision because require is the 3rd parameter of run:,
// not a method on the program or account.
export const counter = program('counter', 'CouNTeR...', counterErrors, {

  increment: ix({
    accounts: {
      counter: p.mut(Counter),  // account named 'counter'
      authority: p.signer(),
    },
    args: { amount: u64 },
    run: ({ counter, authority }, { amount }, require) => {
      //   ^^^^^^^ account    ^^^^^^^^^ args   ^^^^^^^ require — no collision!
      require(authority === counter.authority, 'Unauthorized')    // ✅ autocomplete
      require(counter.isActive, 'NotActive')                       // ✅ autocomplete
      // require(counter.count >= amount, 'Typo')                 // ❌ TS2345
      counter.count += amount
    },
  }),

  decrement: ix({
    accounts: {
      counter: p.mut(Counter),
      authority: p.signer(),
    },
    args: { amount: u64 },
    run: ({ counter, authority }, { amount }, require) => {
      require(authority === counter.authority, 'Unauthorized')
      require(counter.isActive, 'NotActive')
      require(counter.count >= amount, 'BelowZero')
      counter.count -= amount
    },
  }),
})


// ── AMM Program (the complex case) ──

const Pool = account({
  tokenAMint: pubkey,
  tokenBMint: pubkey,
  feeBps: u64,
  isActive: bool,
})

const ammErrors = defineErrors({
  Unauthorized: 'Not the authority',
  PoolDoesNotExist: 'Pool does not exist',
  SlippageExceeded: 'Output below minimum',
  InvalidAmount: 'Amount must be positive',
  InvalidFeeBps: 'Fee too high',
})

export const amm = program('amm', 'AMMx...', ammErrors, {

  swap: ix({
    accounts: {
      pool: p.mut(Pool),
      trader: p.signer(),
    },
    args: { amountIn: u64, minOut: u64 },
    run: ({ pool, trader }, { amountIn, minOut }, require) => {
      require(pool.isActive, 'PoolDoesNotExist')      // ✅
      require(amountIn > 0n, 'InvalidAmount')          // ✅
      require(false, 'SlippageExceeded')               // ✅
      // require(false, 'NotAnError')                  // ❌ TS2345
    },
  }),

  updateFee: ix({
    accounts: {
      pool: p.mut(Pool),
      admin: p.signer(),
    },
    args: { newFeeBps: u64 },
    run: ({ pool, admin }, { newFeeBps }, require) => {
      require(admin === pool.tokenAMint, 'Unauthorized')   // ✅ (name valid)
      require(newFeeBps <= 1000n, 'InvalidFeeBps')         // ✅
    },
  }),
})


// ══════════════════════════════════════════
// WHAT THE DEVELOPER EXPERIENCES
// ══════════════════════════════════════════

// 1. They define errors with defineErrors({ ... })
// 2. They pass errors to program()
// 3. Inside run: handlers, require is the 3rd parameter
// 4. They type require(cond, ' and autocomplete shows ALL registered errors
// 5. If they typo, TypeScript catches it immediately

// NO naming collision between program name and account name.
// NO prefix needed (not amm.require, not counter.require).
// require is ALWAYS the 3rd parameter — consistent, discoverable.
// Type inference flows from program() → errors → ix() → run → require.

// This is the ElysiaJS pattern:
//   Elysia: .error({...}).get('/path', (ctx) => ctx.error('Name'))
//   Ours:   program('...', errors, { handler: ix({ run: (accts, args, require) => require(cond, 'Name') }) })
//
// Both use the SAME technique: generic parameter carries error types
// from the definition site to the usage site via TypeScript inference.

