# program() signature: program('name', 'address', { errors, events }, { instructions })
# account() returns: .seeds('seed', '{field}')
# ix() takes: { accounts, args, run: ({...}, {...}, ctx) => {} }
# p.* methods: p.init, p.mut, p.signer, p.close, p.mint, p.tokenAccount, p.tokenProgram
# ctx.* methods: ctx.require, ctx.emit, ctx.log
# token.* methods: token.transfer, token.mintTo, token.burn
# sol.* methods: sol.timestamp()
# client: betterSol({ cluster, payer, programs })
# test: createTestClient({ programs })

for fname in sorted(os.listdir('.')):
    if not fname.endswith('.md'):
        continue

    with open(fname) as f:
        content = f.read()

    blocks = re.findall(r'```(\w*)\n(.*?)```', content, re.DOTALL)

    for i, (lang, code) in enumerate(blocks):
        block_id = f"{fname} block {i+1}"

        if lang not in ('typescript', 'ts'):
            continue

        # 1. Check program() calls have 4 args: name, address, config, instructions
        program_calls = re.findall(r"program\((.*?)\)", code, re.DOTALL)
        # This is rough — just flag obvious issues

        # 2. Check ix() run handler has correct signature
        run_handlers = re.findall(r"run:\s*\((.*?)\)\s*=>", code, re.DOTALL)
        for handler in run_handlers:
            params = [p.strip() for p in handler.split(',')]
            # Should be: ({accounts}, {args}, ctx) or ({accounts}, {}, ctx)
            if len(params) == 2 and 'ctx' not in params[1]:
                issues.append(f"{block_id}: run handler has 2 params but no ctx: ({handler})")

        # 3. Check for p.* methods that don't exist
        p_calls = re.findall(r"p\.(\w+)\(", code)
        valid_p = {'init', 'mut', 'signer', 'close', 'mint', 'tokenAccount', 'tokenProgram', 
                   'sysvar', 'optional', 'readonly'}
        for call in p_calls:
            if call not in valid_p:
                issues.append(f"{block_id}: unknown p.{call}() method")

        # 4. Check for ctx.* methods that don't exist
        ctx_calls = re.findall(r"ctx\.(\w+)\(", code)
        valid_ctx = {'require', 'emit', 'log'}
        for call in ctx_calls:
            if call not in valid_ctx:
                issues.append(f"{block_id}: unknown ctx.{call}() method")

        # 5. Check for token.* methods that don't exist
        token_calls = re.findall(r"token\.(\w+)\(", code)
        valid_token = {'transfer', 'mintTo', 'burn', 'createAccount', 'approve'}
        for call in token_calls:
            if call not in valid_token:
                issues.append(f"{block_id}: unknown token.{call}() method")

        # 6. Check betterSol config shape
        if 'betterSol(' in code:
            # Should have: cluster?, payer?, programs
            if 'programs:' not in code and 'betterSol' in code:
                issues.append(f"{block_id}: betterSol() without programs key")

        # 7. Check for mixed import patterns
        if "from 'better-sol'" in code and "from 'better-sol/" in code:
            issues.append(f"{block_id}: mixing 'better-sol' and 'better-sol/...' imports")

        # 8. Check account.seeds() pattern
