import re, os

issues = []

# Canonical API surface
VALID_P_METHODS = {'init', 'mut', 'signer', 'close', 'mint', 'tokenAccount', 
                   'tokenProgram', 'systemProgram', 'clock', 'optional', 'readonly'}
VALID_CTX_METHODS = {'require', 'emit', 'log'}
VALID_TOKEN_OPS = {'transfer', 'mintTo', 'burn', 'approve', 'freeze', 'thaw', 'closeAccount'}
VALID_SOL_SYSVARS = {'timestamp', 'slot', 'epoch', 'rentExemptBalance'}
VALID_CLIENT_TOKEN = {'createMint', 'mintTo', 'transfer', 'getBalance', 'getATA'}
VALID_CREATE_TEST = {'createTestSol'}

for fname in sorted(os.listdir('.')) + sorted(os.listdir('examples')):
    fpath = os.path.join('.', fname) if os.path.exists(fname) else os.path.join('examples', fname)
    if not os.path.exists(fpath):
        continue
    if not (fname.endswith('.md') or fname.endswith('.ts')):
        continue

    with open(fpath) as f:
        content = f.read()

    blocks = re.findall(r'```(\w*)\n(.*?)```', content, re.DOTALL)

    for i, (lang, code) in enumerate(blocks):
        block_id = f"{fname}:{i+1}"

        if lang not in ('typescript', 'ts', ''):
            continue

        # p.* methods
        for m in re.findall(r'\bp\.(\w+)\(', code):
            if m not in VALID_P_METHODS:
                issues.append(f"{block_id}: unknown p.{m}()")

        # ctx.* methods  
        for m in re.findall(r'\bctx\.(\w+)\(', code):
            if m not in VALID_CTX_METHODS:
                issues.append(f"{block_id}: unknown ctx.{m}()")

        # token.* in program (on-chain CPI)
        for m in re.findall(r'\btoken\.(\w+)\(', code):
            if m not in VALID_TOKEN_OPS and m not in VALID_CLIENT_TOKEN:
                issues.append(f"{block_id}: unknown token.{m}()")

        # sol.* sysvar calls (not sol.counter, sol.token, etc.)
        for m in re.findall(r'\bsol\.(\w+)\(', code):
            if m not in VALID_SOL_SYSVARS and m not in ('connectWallet', 'transfer', 'getBalance', 
                'createAccount', 'payer', 'rpc', 'counter', 'amm', 'token', 'assert'):
                # Could be a program name — check if it's likely
                pass

        # Check import consistency
        if "from 'better-sol'" in code and "from 'better-sol/program'" in code:
            # Only flag if both imports appear in the same file and one is redundant
            pass

for issue in sorted(set(issues)):
